    <div class="container">
        <div class="calculator">
            <div class="display">
                <div class="expression" id="expression"></div>
                <div class="result" id="result">0</div>
            </div>
            <div class="error" id="error"></div>
            <div class="keypad">
                <button class="btn clear" onclick="clearAll()">C</button>
                <button class="btn operator" onclick="append('(')">(</button>
                <button class="btn operator" onclick="append(')')">)</button>
                <button class="btn operator" onclick="append('/')">÷</button>

                <button class="btn" onclick="append('7')">7</button>
                <button class="btn" onclick="append('8')">8</button>
                <button class="btn" onclick="append('9')">9</button>
                <button class="btn operator" onclick="append('*')">×</button>

                <button class="btn" onclick="append('4')">4</button>
                <button class="btn" onclick="append('5')">5</button>
                <button class="btn" onclick="append('6')">6</button>
                <button class="btn operator" onclick="append('-')">−</button>

                <button class="btn" onclick="append('1')">1</button>
                <button class="btn" onclick="append('2')">2</button>
                <button class="btn" onclick="append('3')">3</button>
                <button class="btn operator" onclick="append('+')">+</button>

                <button class="btn" onclick="append('0')">0</button>
                <button class="btn" onclick="append('.')">.</button>
                <button class="btn" onclick="backspace()">⌫</button>
                <button class="btn equals" onclick="calculate()">=</button>
            </div>
        </div>

        <div class="history-panel">
            <div class="history-header">
                <h2>History</h2>
                <button class="clear-history" onclick="clearHistory()">Clear</button>
            </div>
            <div class="history-list" id="historyList">
                <div class="empty-history">No calculations yet</div>
            </div>
        </div>
    </div>

    <script>
        let currentExpression = '';
        let lastResult = null;

        function updateDisplay() {
            document.getElementById('expression').textContent = currentExpression || '';
            if (lastResult !== null) {
                document.getElementById('result').textContent = lastResult;
            } else if (currentExpression === '') {
                document.getElementById('result').textContent = '0';
            }
        }

        function showError(message) {
            const errorEl = document.getElementById('error');
            errorEl.textContent = message;
            errorEl.classList.add('visible');
            document.getElementById('result').textContent = '—';
            lastResult = null;
        }

        function hideError() {
            document.getElementById('error').classList.remove('visible');
        }

        function append(char) {
            hideError();
            currentExpression += char;
            lastResult = null;
            updateDisplay();
        }

        function clearAll() {
            hideError();
            currentExpression = '';
            lastResult = null;
            updateDisplay();
        }

        function backspace() {
            hideError();
            currentExpression = currentExpression.slice(0, -1);
            lastResult = null;
            updateDisplay();
        }

        async function calculate() {
            if (!currentExpression.trim()) {
                showError('Please enter an expression');
                return;
            }

            hideError();

            try {
                const response = await fetch('/api/calculate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ expression: currentExpression })
                });

                const data = await response.json();

                if (!response.ok) {
                    showError(data.error || 'Calculation failed');
                    return;
                }

                lastResult = data.result;
                document.getElementById('result').textContent = lastResult;
                loadHistory();
            } catch (err) {
                showError('Network error');
            }
        }

        async function loadHistory() {
            try {
                const response = await fetch('/api/history');
                const data = await response.json();

                const listEl = document.getElementById('historyList');

                if (data.entries.length === 0) {
                    listEl.innerHTML = '<div class="empty-history">No calculations yet</div>';
                    return;
                }

                listEl.innerHTML = data.entries.map(entry => `
                    <div class="history-item">
                        <div class="history-expression">${escapeHtml(entry.expression)}</div>
                        <div class="history-result">= ${entry.result}</div>
                    </div>
                `).join('');
            } catch (err) {
                console.error('Failed to load history:', err);
            }
        }

        async function clearHistory() {
            try {
                await fetch('/api/history', { method: 'DELETE' });
                loadHistory();
            } catch (err) {
                console.error('Failed to clear history:', err);
            }
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Keyboard support
        document.addEventListener('keydown', (e) => {
            if (e.key >= '0' && e.key <= '9') append(e.key);
            else if (e.key === '+' || e.key === '-' || e.key === '*' || e.key === '/') append(e.key);
            else if (e.key === '(' || e.key === ')') append(e.key);
            else if (e.key === '.') append('.');
            else if (e.key === 'Enter' || e.key === '=') calculate();
            else if (e.key === 'Escape') clearAll();
            else if (e.key === 'Backspace') backspace();
        });

        // Load history on page load
        loadHistory();
    </script>
</body>
</html>
